(()=>{'use strict';
const D=window.PlantAgentTools,$=id=>document.getElementById(id),R=D.resources,site='https://lidong-huang.github.io/plant-nutrition-lab/',storageKey='plant-lab-agent-v1';
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))||fallback;}catch{return fallback;}},saved=read(storageKey,{});
const state={view:'guide',course:'trial-story',contextCourse:null,events:Array.isArray(saved.events)?saved.events.slice(-500):[],mastered:Array.isArray(saved.mastered)?saved.mastered.filter(id=>D.resource(id)):[],messages:Array.isArray(saved.messages)?saved.messages.filter(m=>['user','assistant'].includes(m.role)&&typeof m.content==='string').slice(-20):[],sessionId:typeof saved.sessionId==='string'?saved.sessionId:(crypto.randomUUID?.()||'learning-'+Date.now()),service:'',classCode:'',configured:false,busy:false,result:null};
try{state.service=localStorage.getItem('plant-agent-service')||'';state.classCode=sessionStorage.getItem('plant-agent-class-code')||'';}catch{}
if(!state.service&&location.protocol!=='file:'&&!location.hostname.endsWith('github.io')&&!location.hostname.endsWith('chatgpt.site'))state.service=location.origin;
const node=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined&&text!==null)n.textContent=text;if(cls)n.className=cls;return n;};
const button=(text,fn,cls)=>{const b=node('button',text,cls);b.type='button';b.addEventListener('click',fn);return b;};
const fmt=(x,n=2)=>Number(x).toFixed(n),pct=x=>x<.0001?'<0.0001':x.toFixed(4),href=r=>location.protocol==='file:'?site+r.path:new URL(r.path,location.href).href;
function save(){try{localStorage.setItem(storageKey,JSON.stringify({sessionId:state.sessionId,events:state.events,mastered:state.mastered,messages:state.messages}));}catch{}}
function record(type,extra={}){state.events.push({type,time:new Date().toISOString(),...extra});state.events=state.events.slice(-500);save();}
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,3000);}
function openLink(r,label){const a=node('a',label);a.href=href(r);a.target='_blank';a.rel='noopener';a.addEventListener('click',()=>record('resource_open',{resourceId:r.id}));return a;}
function setView(view){if(!['guide','chat','analysis','practice'].includes(view))return;state.view=view;document.querySelectorAll('.guide-panel').forEach(p=>p.hidden=p.id!=='panel-'+view);document.querySelectorAll('[data-view]').forEach(b=>{const on=b.dataset.view===view;b.classList.toggle('active',on);if(on)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});if(view==='analysis'&&state.result)requestAnimationFrame(()=>drawCurve($('local-trial-curve'),state.result));if(view==='chat')requestAnimationFrame(()=>$('chat-input').focus({preventScroll:true}));}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));document.querySelectorAll('[data-switch]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.switch)));
function resourceCard(r){const card=node('article',null,'resource-card'),image=node('img');image.src=location.protocol==='file:'?site+r.cover:r.cover;image.alt='';image.loading='lazy';const body=node('div',null,'resource-card-body');body.append(node('small',r.category),node('h3',r.title),node('p',r.description));const actions=node('div',null,'resource-card-actions');actions.append(openLink(r,'看动画 ↗'),button('先理解原理',()=>showConcept(r.id)));body.append(actions);card.append(image,body);return card;}
function showResources(query='',all=false){let results;if(all)results=R;else if(query.trim())results=D.search(query,6);else results=['trial-story','uptake','soil-culture','splitplot'].map(D.resource);$('resource-results').replaceChildren(...results.map(resourceCard));$('resource-heading').textContent=query?'找到'+results.length+'项相关资源':all?'全部13项课程资源':'从这些问题开始';if(!results.length)$('resource-results').append(node('p','暂未找到匹配的知识点，可以试试“根系”“磷处理”或“标准误差”。','field-note'));$('concept-card').hidden=true;}
function showConcept(id){const r=D.resource(id);if(!r)return;state.course=id;state.contextCourse=id;const card=$('concept-card');card.replaceChildren(node('h2',r.title));const ul=node('ul');r.facts.slice(0,3).forEach(t=>ul.append(node('li',t)));card.append(ul);const actions=node('div',null,'concept-actions');actions.append(openLink(r,'打开对应动画 ↗'),button('做一道巩固题',()=>{selectPractice(id);setView('practice');},'text-button'),button('向助教追问',()=>prefill('我正在学习“'+r.title+'”。请围绕这个问题解释：'),'text-button'));card.append(actions);card.hidden=false;card.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'nearest'});}
$('resource-form').addEventListener('submit',e=>{e.preventDefault();const q=$('resource-query').value;showResources(q);record('resource_search',{query:q.slice(0,200)});});document.querySelectorAll('[data-query]').forEach(b=>b.addEventListener('click',()=>{$('resource-query').value=b.dataset.query;$('resource-form').requestSubmit();}));$('all-resources').onclick=()=>{$('resource-query').value='';showResources('',true);};
function drawCurve(canvas,result){if(!canvas)return;const box=canvas.getBoundingClientRect();if(!box.width)return;const w=box.width,h=155,dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(w*dpr);canvas.height=h*dpr;const c=canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);const extent=Math.max(4.5,Math.min(9,Math.abs(result.t)+.8)),X=x=>22+(x+extent)/(2*extent)*(w-38),Y=p=>h-26-p*(h-48)/.42,baseline=Y(0),inTail=x=>result.alternative==='greater'?x>=result.t:result.alternative==='less'?x<=result.t:Math.abs(x)>=Math.abs(result.t);c.strokeStyle='#c1ccb1';c.beginPath();c.moveTo(X(-extent),baseline);c.lineTo(X(extent),baseline);c.stroke();for(let i=0;i<240;i++){const x=-extent+2*extent*i/240,dx=2*extent/240;if(inTail(x)){c.fillStyle='#c7a36788';c.fillRect(X(x),Y(StudentTMath.pdf(x,result.df)),X(x+dx)-X(x)+.5,baseline-Y(StudentTMath.pdf(x,result.df)));}}c.beginPath();for(let i=0;i<=240;i++){const x=-extent+i/240*extent*2,y=Y(StudentTMath.pdf(x,result.df));i?c.lineTo(X(x),y):c.moveTo(X(x),y);}c.strokeStyle='#ad8c50';c.lineWidth=1.8;c.stroke();c.font='10px Georgia,serif';c.fillStyle='#8a9879';c.textAlign='center';for(const v of [-4,-2,0,2,4])if(Math.abs(v)<=extent)c.fillText(String(v),X(v),h-9);const marker=Math.max(-extent+.1,Math.min(extent-.1,result.t));c.strokeStyle='#81976a';c.setLineDash([3,4]);c.beginPath();c.moveTo(X(marker),baseline);c.lineTo(X(marker),17);c.stroke();c.setLineDash([]);c.textAlign=marker>extent*.5?'right':marker<-extent*.5?'left':'center';c.fillStyle='#8c7546';c.fillText('t='+fmt(result.t)+(Math.abs(result.t)>extent?'（视窗外）':''),X(marker),12);}
function statsResult(result,full=true){const wrap=node('div'),grid=node('div',null,'stats-grid');for(const[label,value]of [['平均值 x̄',fmt(result.mean)],['样本标准差 s',fmt(result.s)],['样本标准误差',fmt(result.se)],['t 值',fmt(result.t)],['自由度 df',String(result.df)],['p 值',pct(result.p)]]){const cell=node('div',null,'stat-cell');cell.append(node('small',label),node('b',value));grid.append(cell);}wrap.append(grid);const canvas=node('canvas',null,'trial-curve');if(full)canvas.id='local-trial-curve';canvas.setAttribute('aria-label','t分布及本次结果的尾部区域');wrap.append(canvas);const side={greater:'偏高',less:'偏低','two-sided':'不同'}[result.alternative],conclusion=node('div',null,'trial-conclusion');conclusion.append(node('b',result.significant?'相较基准，结果显著'+side:'尚未发现显著'+side+'的证据'),node('span','p '+(result.significant?'＜':'≥')+' α＝'+result.alpha),node('small','(x̄ − '+result.baseline+') / (s/√n)＝'+fmt(result.t)));wrap.append(conclusion);const interval=result.confidenceInterval;wrap.append(node('p',Math.round(interval.level*100)+'%双侧置信区间：['+fmt(interval.lower)+'，'+fmt(interval.upper)+']','trial-interval'));if(full){const details=node('details',null,'field-note');details.append(node('summary','本次判断的适用条件'),node('p',result.assumptions.join('；')+'。'+result.scope));wrap.append(details);const actions=node('div',null,'result-actions');actions.append(button('请助教解释这次结果',()=>prefill('独立重复数据为'+result.values.join('、')+'，固定基准'+result.baseline+'，事先约定'+{greater:'右尾偏高',less:'左尾偏低','two-sided':'双侧差异'}[result.alternative]+'，α='+result.alpha+'。请核算并解释样本标准误差与尾部概率。'),'text-button'),button('练习相同知识点',()=>{selectPractice('trial-story');setView('practice');},'text-button'));wrap.append(actions);}requestAnimationFrame(()=>drawCurve(canvas,result));return wrap;}
$('analysis-form').addEventListener('submit',e=>{e.preventDefault();$('analysis-error').textContent='';try{const r=D.trial({values:D.parseValues($('trial-values').value),baseline:Number($('baseline').value),alpha:Number($('trial-alpha').value),alternative:$('alternative').value});state.result=r;$('analysis-result').replaceChildren(statsResult(r));record('trial_calculate',{n:r.n,baseline:r.baseline,alternative:r.alternative,alpha:r.alpha,mean:r.mean,se:r.se,t:r.t,p:r.p,dataSource:$('data-source').dataset.source||'user_input'});}catch(err){$('analysis-error').textContent=err.message;}});
document.querySelectorAll('[data-example]').forEach(b=>b.addEventListener('click',()=>{$('trial-values').value=b.dataset.example==='first'?'520，540，560，580':'490，530，570，610';$('baseline').value='500';$('alternative').value='greater';$('trial-alpha').value='0.05';$('data-source').textContent='已载入教学示例，用于比较相同均值、不同波动。';$('data-source').dataset.source='teaching_example';}));$('trial-values').oninput=()=>{$('data-source').textContent='你输入的数据：请确认每个数代表一个独立重复。';$('data-source').dataset.source='user_input';};
R.forEach(r=>{const option=node('option',r.title);option.value=r.id;$('practice-topic').append(option);});
function noteMastered(id){if(!state.mastered.includes(id))state.mastered.push(id);$('practice-progress').textContent='已掌握 '+state.mastered.length+' / '+R.length;save();}
function practiceUI(question,inline=false){const card=node('div',null,inline?'inline-practice':''),heading=node(inline?'h3':'h2',question.question),options=node('div',null,'practice-options'),feedback=node('div',null,'practice-feedback');feedback.setAttribute('role','status');card.append(heading,options,feedback);question.options.forEach((text,i)=>{const b=button('',()=>{const answer=D.grade(question.id,i);record('practice_answer',{resourceId:question.resourceId,questionId:question.id,choice:i,correct:answer.correct});options.querySelectorAll('button').forEach(x=>x.classList.remove('wrong'));b.classList.add(answer.correct?'correct':'wrong');feedback.className='practice-feedback'+(answer.correct?' success':'');feedback.textContent=answer.correct?answer.explanation:'提示：'+answer.hint;if(answer.correct){options.querySelectorAll('button').forEach(x=>x.disabled=true);noteMastered(question.resourceId);const actions=node('div',null,'practice-actions');actions.append(openLink(D.resource(question.resourceId),'再看对应动画 ↗'));if(!inline)actions.append(button('换个知识点 →',()=>{const at=R.findIndex(r=>r.id===question.resourceId);selectPractice(R[(at+1)%R.length].id);},'primary-button'));card.append(actions);}});b.append(node('span',String.fromCharCode(65+i)),document.createTextNode(text));options.append(b);});return card;}
function selectPractice(id){state.course=D.resource(id)?id:'trial-story';$('practice-topic').value=state.course;$('practice-card').replaceChildren(practiceUI(D.practice(state.course)));$('practice-progress').textContent='已掌握 '+state.mastered.length+' / '+R.length;}
$('practice-topic').onchange=()=>selectPractice($('practice-topic').value);
function appendText(parent,text){for(const line of text.split(/\n{2,}/)){const p=node('p',line.replace(/^#{1,4}\s+/gm,''));parent.append(p);}}
function renderMessage(m){const turn=node('div',null,'chat-turn '+m.role);if(m.role==='user'){turn.append(node('p',m.content));return turn;}const body=node('div',null,'assistant-body');body.append(node('small','植知 / DeepSeek'));if(Array.isArray(m.trace)){const traces=node('div',null,'tool-trace');for(const t of m.trace.slice(0,10))if(typeof t.label==='string')traces.append(node('span',(t.success?'✓ ':'')+t.label));body.append(traces);}appendText(body,m.content);const links=node('div',null,'chat-sources');for(const id of (m.sourceIds||[])){const r=D.resource(id);if(r)links.append(openLink(r,r.title+' ↗'));}if(links.childNodes.length)body.append(links);for(const input of (m.calcInputs||[]).slice(0,2)){try{body.append(statsResult(D.trial(input),false));}catch{}}for(const id of (m.practiceIds||[]).slice(0,1)){if(D.resource(id))body.append(practiceUI(D.practice(id),true));}turn.append(body);return turn;}
function renderChat(){if(!state.messages.length)return;$('chat-messages').replaceChildren(...state.messages.map(renderMessage));}
function prefill(text){setView('chat');$('chat-input').value=text;$('chat-input').focus();}
document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>prefill(b.dataset.prompt));$('new-chat').onclick=()=>{state.messages=[];save();$('chat-messages').replaceChildren(node('p','新的对话已开始。可以带着一个知识点或一组数据提问。','field-note'));};
function setConnected(configured,label){state.configured=!!configured;$('connection').classList.toggle('connected',state.configured);$('connection-label').textContent=label||'DeepSeek '+(state.configured?'已配置':'待连接');$('chat-connection-note').hidden=state.configured;$('send-chat').disabled=!state.configured||state.busy;}
async function status(base=state.service){if(!base)return null;const response=await fetch(base+'/api/status',{signal:AbortSignal.timeout(7000),credentials:'omit'});if(!response.ok)throw Error('服务地址暂时无法连接。');const data=await response.json();if(data.provider!=='DeepSeek'||typeof data.configured!=='boolean')throw Error('该地址没有提供植知导学服务。');return data;}
function connectionDialog(){$('service-url').value=state.service;$('class-code').value=state.classCode;$('connection-feedback').textContent='DeepSeek API密钥由教师在服务端配置。';$('connection-dialog').showModal();}
$('connection').onclick=connectionDialog;$('chat-connect').onclick=connectionDialog;$('close-connection').onclick=()=>$('connection-dialog').close();
function validService(raw){const value=raw.trim();if(!value)throw Error('请填写教师提供的服务地址。');const u=new URL(value);if(u.username||u.password||u.search||u.hash||!['https:','http:'].includes(u.protocol)||!['','/'].includes(u.pathname))throw Error('请填写不带路径、口令和参数的服务根地址。');if(u.protocol==='http:'&&!['localhost','127.0.0.1','[::1]'].includes(u.hostname))throw Error('校内部署请使用https服务地址。');return u.origin;}
$('connection-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const base=validService($('service-url').value),info=await status(base);state.service=base;state.classCode=$('class-code').value.trim();try{localStorage.setItem('plant-agent-service',base);sessionStorage.setItem('plant-agent-class-code',state.classCode);}catch{}setConnected(info.configured,info.configured?undefined:'DeepSeek 尚未启用');$('connection-feedback').textContent=info.configured?(info.requiresClassCode&&!state.classCode?'服务已连接，请填写本课堂的访问口令。':'服务已连接，可以开始提问。'):'页面已连接服务，但服务端尚未配置DeepSeek密钥。';if(info.configured&&(!info.requiresClassCode||state.classCode)){$('connection-dialog').close();toast('DeepSeek导学服务已连接');}}catch(err){$('connection-feedback').textContent=err instanceof TypeError?'请输入有效地址，或检查服务是否在线。':err.message;}finally{b.disabled=false;}};
let controller=null;$('chat-form').addEventListener('submit',async e=>{e.preventDefault();if(!state.configured||state.busy)return;const text=$('chat-input').value.trim();if(!text)return;const history=state.messages.slice(-10).map(m=>({role:m.role,content:m.content})),message={role:'user',content:text};state.messages.push(message);renderChat();$('chat-input').value='';state.busy=true;$('new-chat').disabled=true;$('send-chat').disabled=true;$('stop-chat').hidden=false;const waiting=node('div','正在查找课程资料并组织回答…','field-note');$('chat-messages').append(waiting);controller=new AbortController();const timer=setTimeout(()=>controller.abort(),95000);try{const response=await fetch(state.service+'/api/chat',{method:'POST',headers:{'Content-Type':'application/json',...(state.classCode?{Authorization:'Bearer '+state.classCode}:{})},body:JSON.stringify({message:text,history,courseId:state.contextCourse,sessionId:state.sessionId}),signal:controller.signal,credentials:'omit'});const payload=await response.json();if(!response.ok||typeof payload.answer!=='string')throw Error(payload.error?.message||'暂时没有收到回答，请稍后重试。');setConnected(true,'DeepSeek 已连接');const m={role:'assistant',content:payload.answer,sourceIds:(payload.sources||[]).map(x=>x.id).filter(id=>D.resource(id)),calcInputs:(payload.calculations||[]).map(x=>({values:x.values,baseline:x.baseline,alpha:x.alpha,alternative:x.alternative})),practiceIds:(payload.practices||[]).map(x=>x.resourceId).filter(id=>D.resource(id)),trace:payload.trace};state.messages.push(m);state.messages=state.messages.slice(-20);waiting.remove();$('chat-messages').append(renderMessage(m));record('chat_complete',{provider:'DeepSeek',tools:(payload.trace||[]).map(t=>t.tool),sourceIds:m.sourceIds,usage:payload.usage});save();}catch(err){waiting.remove();const failure=node('div',err.name==='AbortError'?'本次回答已停止。可以修改问题后重试。':err.message,'chat-error');$('chat-messages').append(failure);state.messages.pop();$('chat-input').value=text;}finally{clearTimeout(timer);state.busy=false;$('new-chat').disabled=false;$('stop-chat').hidden=true;$('send-chat').disabled=!state.configured;controller=null;}});
$('stop-chat').onclick=()=>controller?.abort();$('chat-input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('chat-form').requestSubmit();}};
$('export-record').onclick=()=>{const payload={resource:'植知智能导学',exportedAt:new Date().toISOString(),sessionId:state.sessionId,scope:'本浏览器实际发生的操作；记录可编辑，不作为独立认证成绩。',mastered:state.mastered,events:state.events,conversation:state.messages.map(m=>({role:m.role,content:m.content}))},url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'})),a=node('a');a.href=url;a.download='植知导学学习记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);};
$('export-mobile').onclick=()=>$('export-record').click();
window.addEventListener('resize',()=>{if(state.view==='analysis'&&state.result)drawCurve($('local-trial-curve'),state.result);});
showResources();selectPractice(state.course);renderChat();if(state.service)status().then(info=>setConnected(info?.configured)).catch(()=>setConnected(false,'DeepSeek 待连接'));
const requested=new URLSearchParams(location.search).get('course');if(D.resource(requested)){state.course=requested;state.contextCourse=requested;$('resource-query').value=D.resource(requested).title;showResources(D.resource(requested).title);selectPractice(requested);}
Object.defineProperty(window,'plantAgentDiagnostics',{get:()=>({view:state.view,configured:state.configured,busy:state.busy,eventCount:state.events.length,mastered:state.mastered.slice(),messageCount:state.messages.length,result:state.result,resourceCount:R.length})});
})();
